// Black-box reimplementation of the Python `canonicaljson` package.
// Reproduces the chunk boundaries of CPython's pure-Python
// json.encoder._make_iterencode (ensure_ascii=False, sort_keys=True).

import { escapeJsonString } from './pyescape.mjs';
import { reprPythonFloat } from './pyfloat.mjs';
import { utf8Encode } from './pybytes.mjs';

// Compare strings by Unicode code point (not UTF-16 code unit).
function compareKeysByCodePoint(a, b) {
    const ca = Array.from(a);
    const cb = Array.from(b);
    const n = Math.min(ca.length, cb.length);
    for (let i = 0; i < n; i++) {
        const pa = ca[i].codePointAt(0);
        const pb = cb[i].codePointAt(0);
        if (pa !== pb) {
            return pa - pb;
        }
    }
    return ca.length - cb.length;
}

function rejectBadFloat(x) {
    if (Number.isNaN(x) || !Number.isFinite(x)) {
        const err = new Error(
            'Out of range float values are not JSON compliant: ' + reprPythonFloat(x)
        );
        err.name = 'ValueError';
        throw err;
    }
}

function* dictEncode(obj, level, indent, itemSeparator, keySeparator) {
    const keys = Object.keys(obj);
    if (keys.length === 0) {
        yield '{}';
        return;
    }
    yield '{';
    let effectiveItemSep = itemSeparator;
    if (indent !== null) {
        level += 1;
        const newlineIndent = '\n' + indent.repeat(level);
        yield newlineIndent;
        effectiveItemSep = itemSeparator + newlineIndent;
    }
    keys.sort(compareKeysByCodePoint);
    let first = true;
    for (const key of keys) {
        if (!first) {
            yield effectiveItemSep;
        }
        first = false;
        yield escapeJsonString(key);
        yield keySeparator;
        yield* valueEncode(obj[key], level, indent, itemSeparator, keySeparator);
    }
    if (indent !== null) {
        level -= 1;
        yield '\n' + indent.repeat(level);
    }
    yield '}';
}

// Value encoding inside a dict: no buffer prefix, each chunk yielded as-is.
function* valueEncode(value, level, indent, itemSeparator, keySeparator) {
    if (typeof value === 'string') {
        yield escapeJsonString(value);
    } else if (typeof value === 'bigint') {
        yield value.toString();
    } else if (typeof value === 'number') {
        rejectBadFloat(value);
        yield reprPythonFloat(value);
    } else if (Array.isArray(value)) {
        yield* listEncode(value, level, indent, itemSeparator, keySeparator);
    } else {
        yield* dictEncode(value, level, indent, itemSeparator, keySeparator);
    }
}

function* listEncode(lst, level, indent, itemSeparator, keySeparator) {
    if (lst.length === 0) {
        yield '[]';
        return;
    }
    let buf = '[';
    let sep = itemSeparator;
    if (indent !== null) {
        level += 1;
        const newlineIndent = '\n' + indent.repeat(level);
        sep = itemSeparator + newlineIndent;
        buf += newlineIndent;
    }
    let first = true;
    for (const value of lst) {
        if (!first) {
            buf = sep;
        }
        first = false;
        if (typeof value === 'string') {
            yield buf + escapeJsonString(value);
        } else if (typeof value === 'bigint') {
            yield buf + value.toString();
        } else if (typeof value === 'number') {
            rejectBadFloat(value);
            yield buf + reprPythonFloat(value);
        } else {
            yield buf;
            if (Array.isArray(value)) {
                yield* listEncode(value, level, indent, itemSeparator, keySeparator);
            } else {
                yield* dictEncode(value, level, indent, itemSeparator, keySeparator);
            }
        }
    }
    if (indent !== null) {
        level -= 1;
        yield '\n' + indent.repeat(level);
    }
    yield ']';
}

function* iterencode(value, indent, itemSeparator, keySeparator) {
    if (typeof value === 'string') {
        yield escapeJsonString(value);
    } else if (typeof value === 'bigint') {
        yield value.toString();
    } else if (typeof value === 'number') {
        rejectBadFloat(value);
        yield reprPythonFloat(value);
    } else if (Array.isArray(value)) {
        yield* listEncode(value, 0, indent, itemSeparator, keySeparator);
    } else {
        yield* dictEncode(value, 0, indent, itemSeparator, keySeparator);
    }
}

export function* iterencodeCanonicalJson(value) {
    yield* iterencode(value, null, ',', ':');
}

export function encodeCanonicalJson(value) {
    let joined = '';
    for (const chunk of iterencodeCanonicalJson(value)) {
        joined += chunk;
    }
    return utf8Encode(joined);
}

export function encodePrettyPrintedJson(value) {
    let joined = '';
    for (const chunk of iterencode(value, '    ', ',', ': ')) {
        joined += chunk;
    }
    return utf8Encode(joined);
}
